do $$declare b jsonb;device uuid;n integer:=0;credential uuid;session uuid;begin
 for b in select x.value from corpus c,jsonb_array_elements(c.value->'baselines') x loop
  n:=n+1;device:=(b#>>'{manifest,deviceId}')::uuid;
  credential:=('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;session:=('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
  insert into public.shop_devices(shop_device_id,shop_id,device_identifier,display_name,device_type,status) values(device,'10000000-0000-4000-8000-000000403019','SYNTHETIC-PUB-'||n,'Synthetic POS '||n,'pos','active');
  insert into public.pos_device_credentials(pos_device_credential_id,shop_id,shop_device_id,staff_id,token_hash,staff_credential_version,expires_at)
   values(credential,'10000000-0000-4000-8000-000000403019',device,'30000000-0000-4000-8000-000000403019','sha256:'||repeat(n::text,64),7,clock_timestamp()+interval '1 hour');
  insert into public.pos_sessions(pos_session_id,shop_id,shop_device_id,staff_id,pos_device_credential_id,session_token_hash,staff_credential_version,issued_at,expires_at)
   values(session,'10000000-0000-4000-8000-000000403019',device,'30000000-0000-4000-8000-000000403019',credential,'sha256:'||repeat((n+2)::text,64),7,clock_timestamp()-interval '1 minute',clock_timestamp()+interval '30 minutes');
 end loop;
end;$$;

select set_config('request.jwt.claim.role','service_role',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
create function pg_temp.baseline_request(n integer,op text,p jsonb) returns jsonb language sql as $$
 select public.payment_history_device_v2('10000000-0000-4000-8000-000000403019',
  (value#>>array['baselines',(n-1)::text,'manifest','deviceId'])::uuid,'30000000-0000-4000-8000-000000403019',('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
  'sha256:'||repeat(n::text,64),'sha256:'||repeat((n+2)::text,64),7,'baseline_'||op,p)->'result' from corpus;
$$;

create function pg_temp.upload_payload() returns jsonb language sql as $$
 select jsonb_build_object('request_key','a0000000-0000-4000-8000-000000403019','file_name','synthetic.w7history.zip','sha256',repeat('a',64),'byte_length','1234');
$$;
select ok(not has_function_privilege('service_role','app_private.payment_history_local_baseline_transfer_v2(uuid,uuid,uuid,uuid,text,text,integer,text,jsonb)','EXECUTE'),'private transfer helper cannot bypass the authenticated public boundary');
select ok((select relrowsecurity from pg_class where oid='app_private.payment_history_baseline_upload_intents'::regclass),'private mapping also has RLS');
select lives_ok($$insert into state values('first',pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()))$$,'first upload admission uses the existing engine');
select is(pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()),(select value from state where key='first'),'lost response returns the original owned upload');
select is((select count(*) from public.payment_history_uploads),1::bigint,'replay does not leak another pending object');
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()||jsonb_build_object('sha256',repeat('b',64)))$$,'23505','payment_history_idempotency_conflict','changed bytes cannot reuse intent');
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()||jsonb_build_object('byte_length','1235'))$$,'23505','payment_history_idempotency_conflict','changed length cannot reuse intent');
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()||jsonb_build_object('file_name','other.w7history.zip'))$$,'23505','payment_history_idempotency_conflict','changed source name cannot reuse intent');
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()||jsonb_build_object('byte_length',1234))$$,'22023','payment_history_upload_invalid','length uses a bounded exact string');
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()||jsonb_build_object('request_key','00000000-0000-0000-0000-000000000000'))$$,'22023','payment_history_upload_invalid','zero intent is denied');
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload()||jsonb_build_object('file_name','../other.w7history.zip'))$$,'22023','payment_history_upload_invalid','archive path is not a client supplied object key');
select throws_ok($$select pg_temp.baseline_request(2,'upload_status',jsonb_build_object('upload_id',(select value->>'upload_id' from state where key='first')))$$,'42501','payment_history_upload_actor_mismatch','peer cannot observe source status');
select throws_ok($$select pg_temp.baseline_request(2,'upload_ready',jsonb_build_object('upload_id',(select value->>'upload_id' from state where key='first')))$$,'42501','payment_history_upload_actor_mismatch','peer cannot make the source ready');
select throws_ok($$select pg_temp.baseline_request(2,'start',jsonb_build_object('upload_id',(select value->>'upload_id' from state where key='first')))$$,'42501','payment_history_upload_actor_mismatch','peer cannot start migration with another device source');
select isnt(pg_temp.baseline_request(2,'upload_create',pg_temp.upload_payload())->>'upload_id',(select value->>'upload_id' from state where key='first'),'same request key in another device creates its own source');
select is(pg_temp.baseline_request(1,'upload_status',jsonb_build_object('upload_id',(select value->>'upload_id' from state where key='first')))->>'state','pending','source starts pending verification');
select is(pg_temp.baseline_request(1,'upload_ready',jsonb_build_object('upload_id',(select value->>'upload_id' from state where key='first')))->>'state','uploaded','ready schedules the existing verification worker');
select is(pg_temp.baseline_request(1,'upload_status',jsonb_build_object('upload_id',(select value->>'upload_id' from state where key='first')))->>'state','uploaded','ready never claims hash verification');
select throws_ok($$delete from app_private.payment_history_baseline_upload_intents$$,'55000','payment_history_baseline_upload_immutable','intent cannot be erased');
select throws_ok($$update app_private.payment_history_baseline_upload_intents set request_key=gen_random_uuid()$$,'55000','payment_history_baseline_upload_immutable','intent cannot be reassigned');
create function pg_temp.admit_baseline(n integer) returns jsonb language plpgsql as $$
declare f jsonb;start jsonb;l jsonb;review jsonb;upload uuid:=gen_random_uuid();receipt jsonb;begin
 select value->'baselines'->(n-1) into f from corpus;
 upload:=(pg_temp.baseline_request(n,'upload_create',jsonb_build_object('request_key',gen_random_uuid(),'file_name','synthetic.w7history.zip',
  'sha256',f->>'archiveSha256','byte_length',f->>'byteLength'))->>'upload_id')::uuid;
 update public.payment_history_uploads set state='verified',verified_at=clock_timestamp() where upload_id=upload;
 start:=pg_temp.baseline_request(n,'start',jsonb_build_object('request_key',gen_random_uuid(),'upload_id',upload,'local_dataset_id',f#>>'{manifest,localDatasetId}',
  'data_revision',f#>>'{manifest,dataRevision}','restore_epoch',f#>>'{manifest,restoreEpoch}','restore_lineage_id',f#>>'{manifest,restoreLineageId}','writer_epoch','1'));
 l:=public.payment_history_migration_worker_v1('claim','{}')->'run';
 if l->>'run_id' is distinct from start->>'run_id' then raise exception 'fixture_worker_claim_mismatch';end if;
 if jsonb_array_length(f->'objects')>0 then perform public.payment_history_migration_worker_v1('stage_objects',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'objects'));end if;
 if jsonb_array_length(f->'movements')>0 then perform public.payment_history_migration_worker_v1('stage_movements',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'movements'));end if;
 perform public.payment_history_migration_worker_v1('finish',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','raw_manifest',f->>'rawManifest','analysis_digest',f->>'analysisDigest'));
 review:=pg_temp.baseline_request(n,'review',jsonb_build_object('run_id',start->>'run_id'));
 if review->>'can_apply' is distinct from 'true' then raise exception 'fixture_baseline_not_applicable';end if;
 receipt:=pg_temp.baseline_request(n,'apply',jsonb_build_object('run_id',start->>'run_id','request_key',gen_random_uuid(),'review_digest',review->>'review_digest'));
 return receipt;
end;$$;
create function pg_temp.case_input(label text) returns jsonb language sql as $$
 select x from corpus c,jsonb_array_elements(c.value->'cases') x where x->>'name'=label;
$$;
create function pg_temp.delivery_payload(label text,seq bigint) returns jsonb language sql as $$
 select jsonb_build_object('operation_id',p.operation_id,'grant_id',p.grant_id,'content_digest',p.content_digest,'local_revision',
  ((x->>'base_revision')::bigint+(x#>>'{local_decision,revision_delta}')::bigint)::text,'local_sequence',seq::text,'local_receipt_json',x->>'local_receipt_json')
 from pg_temp.case_input(label) x join public.payment_history_local_publications p on p.operation_id=(x->>'operation_id')::uuid;
$$;
create function pg_temp.make_witness(label text,outcome text,seq bigint default null) returns text language plpgsql as $$
declare x jsonb;p public.payment_history_local_publications;c public.payment_history_local_writer_contexts;begin
 x:=pg_temp.case_input(label);
 select * into p from public.payment_history_local_publications where operation_id=(x->>'operation_id')::uuid;
 select * into c from public.payment_history_local_writer_contexts where shop_id=(x->>'shop_id')::uuid and shop_device_id=(x->>'device_id')::uuid;
 return json_build_object('schema_version',1,'outcome',outcome,'operation_kind',x->>'kind','local_nonce',md5('synthetic-nonce:'||(x->>'operation_id'))::uuid,
 'grant_id',p.grant_id,'operation_id',x->>'operation_id','shop_id',x->>'shop_id','device_id',x->>'device_id','local_dataset_id',x->>'local_dataset_id',
 'server_dataset_id',(select dataset_id from public.payment_history_runtime where shop_id=(x->>'shop_id')::uuid),'restore_epoch',x->>'restore_epoch',
 'restore_lineage_id',x->>'restore_lineage_id','writer_epoch','1','content_digest',x->>'content_digest','request_fingerprint',x->>'request_fingerprint',
 'base_revision',x->>'base_revision','local_revision',case when outcome='aborted' then x->>'base_revision' else
 ((x->>'base_revision')::bigint+(x#>>'{local_decision,revision_delta}')::bigint)::text end,
 'local_sequence',case when outcome='aborted' then c.last_local_sequence::text else coalesce(seq,7)::text end,
 'local_receipt_sha256',case when outcome='committed' then x->>'local_receipt_sha256' else null end,
 'proof_sha256',case when p.authorized_proof is not null then encode(extensions.digest(convert_to(p.authorized_proof::text,'UTF8'),'sha256'),'hex') else null end,
 'admission_id',case when outcome='committed' then 'f0000000-0000-4000-8000-000000403019'::uuid else null end,
 'remaining_milliseconds',case when outcome='committed' then 50000 else null end,
 'request_elapsed_milliseconds',case when outcome='committed' then 7 else null end,
 'elapsed_milliseconds',case when outcome='committed' then 50 else null end,
 'minimum_remaining_milliseconds',case when outcome='committed' then 10000 else null end)::text;
end;$$;

-- Real authenticated SQL boundary and engines; worker inputs and monotonic
-- commit witnesses remain synthetic component fixtures, not WPF/HTTP E2E.
create function pg_temp.composed(label text,op text,p jsonb) returns jsonb language sql as $$
 select public.payment_history_device_v2((x->>'shop_id')::uuid,(x->>'device_id')::uuid,'30000000-0000-4000-8000-000000403019',
  ('60000000-0000-4000-8000-'||lpad(case when x->>'device_id'='20000000-0000-4000-8000-000000403019' then '1' else '2' end,12,'0'))::uuid,
  'sha256:'||repeat(case when x->>'device_id'='20000000-0000-4000-8000-000000403019' then '1' else '2' end,64),
  'sha256:'||repeat(case when x->>'device_id'='20000000-0000-4000-8000-000000403019' then '3' else '4' end,64),7,op,p)->'result'
 from pg_temp.case_input(label) x;
$$;
create function pg_temp.stage_public(label text) returns uuid language plpgsql as $$
declare x jsonb;page jsonb;begin
 x:=pg_temp.case_input(label);
 perform pg_temp.composed(label,'local_prepare',(x-array['name','shop_id','device_id','pages','local_receipt_json','local_receipt_sha256','local_decision'])||
  jsonb_build_object('writer_epoch','1','protocol_version',2,'local_nonce',md5('synthetic-nonce:'||(x->>'operation_id'))::uuid));
 for page in select value from jsonb_array_elements(x->'pages') loop
  perform pg_temp.composed(label,'local_stage',page||jsonb_build_object('operation_id',x->>'operation_id','content_digest',x->>'content_digest'));
 end loop;return (x->>'operation_id')::uuid;
end;$$;
create function pg_temp.review_public(label text) returns jsonb language sql as $$
 select pg_temp.composed(label,'local_review',jsonb_build_object('operation_id',x->>'operation_id','content_digest',x->>'content_digest','ordinal',1)) from pg_temp.case_input(label) x;
$$;
create function pg_temp.positive_public(label text) returns jsonb language sql as $$
 select pg_temp.composed(label,'local_reconcile',pg_temp.delivery_payload(label,7)||jsonb_build_object('witness_json',pg_temp.make_witness(label,'committed',7),
  'local_proof_json',(select authorized_proof::text from public.payment_history_local_publications where operation_id=(pg_temp.case_input(label)->>'operation_id')::uuid)));
$$;


select ok(not has_function_privilege('anon','public.payment_history_device_v2(uuid,uuid,uuid,uuid,text,text,integer,text,jsonb)','EXECUTE'),'anonymous cannot execute composed device RPC');
select ok(not has_function_privilege('authenticated','public.payment_history_device_v2(uuid,uuid,uuid,uuid,text,text,integer,text,jsonb)','EXECUTE'),'browser JWT cannot execute device RPC');
select ok(has_function_privilege('service_role','public.payment_history_device_v2(uuid,uuid,uuid,uuid,text,text,integer,text,jsonb)','EXECUTE'),'service has the lease-checking RPC only');
select throws_ok($$select pg_temp.composed('a-new','baseline_resume','{}')$$,'22023','payment_history_operation_invalid','raw resume cannot bypass durable recovery');
select throws_ok($$select pg_temp.composed('a-new','baseline_cancel','{}')$$,'22023','payment_history_operation_invalid','raw cancellation is not a device primitive');
select throws_ok($$select pg_temp.composed('a-new','local_deliver','{}')$$,'22023','payment_history_operation_invalid','witness-free delivery is closed');
select lives_ok($$insert into state values('public-baseline-a',pg_temp.admit_baseline(1))$$,'device A baseline uses actual upload intent, worker, review and Apply');
select lives_ok($$insert into state values('public-baseline-b',pg_temp.admit_baseline(2))$$,'device B has its independently verified original baseline');
select is((select count(*) from public.payment_history_local_writer_contexts where source_snapshot_id is not null),2::bigint,'both actual baseline contexts are bound');
-- The publication corpus explicitly approves these synthetic source files.
-- Baseline merchant evidence is carried by the real baseline engine; the
-- independent new import still requires its own existing policy evidence.
do $$declare hashes jsonb;begin
 select jsonb_agg(distinct rec#>>'{fields,sha256}') into hashes from corpus c,jsonb_array_elements(c.value->'cases') x,
  jsonb_array_elements(x->'pages') page,jsonb_array_elements((page->>'page_json')::jsonb) rec where rec->>'kind'='file';
 insert into public.payment_history_evidence(evidence_id,shop_id,kind,verification_level,status,policy_version,reference,scope,actor_kind,actor_id,verified_at)
 select gen_random_uuid(),m.shop_id,k.kind,'operator_attested','verified','synthetic-v1','Synthetic verified corpus policy',
  jsonb_build_object('merchant_id',m.merchant_id,'file_sha256',hashes,'from_ticks','0','to_ticks','3155378975999999999','native_start_ticks','638712864000000000'),
  'pos_staff_manager','30000000-0000-4000-8000-000000403019',clock_timestamp()
 from public.payment_history_merchants m cross join(values('native_start'),('legacy_currency')) k(kind)
 where m.shop_id='10000000-0000-4000-8000-000000403019';
end;$$;
select lives_ok($$select pg_temp.stage_public('a-new')$$,'authenticated boundary prepares and stages CLR content with immutable nonce');
select lives_ok($$insert into state values('public-review',pg_temp.review_public('a-new'))$$,'public review delegates to actual bounded economic review');
select lives_ok($$insert into state select 'public-grant',pg_temp.composed('a-new','local_authorize',jsonb_build_object('operation_id',x->>'operation_id','content_digest',x->>'content_digest','review_token',(select value->>'review_token' from state where key='public-review'))) from pg_temp.case_input('a-new') x$$,'public authorization binds exact reviewed root');
select is((select value#>'{proof,local_decision}' from state where key='public-grant'),pg_temp.case_input('a-new')->'local_decision','server economic decision matches real CLR corpus');
select lives_ok($$insert into state values('public-positive',pg_temp.positive_public('a-new'))$$,'positive witness and economic delivery commit through the one public boundary');
select is(pg_temp.positive_public('a-new'),(select value from state where key='public-positive'),'lost ACK returns original canonical receipt with no second financial write');
select is((select count(*) from public.payment_history_receipts where request_key=(pg_temp.case_input('a-new')->>'operation_id')::uuid),1::bigint,'one original operation owns one permanent economic receipt');
select is(pg_temp.composed('a-new','local_receipt',jsonb_build_object('operation_id',pg_temp.case_input('a-new')->>'operation_id','content_digest',pg_temp.case_input('a-new')->>'content_digest')),
 (select value from state where key='public-positive'),'receipt lookup uses the same canonical result');
select lives_ok($$select pg_temp.composed('a-duplicate','local_abort',jsonb_build_object('operation_id',pg_temp.case_input('a-duplicate')->>'operation_id','content_digest',pg_temp.case_input('a-duplicate')->>'content_digest','witness_json',pg_temp.make_witness('a-duplicate','aborted')))$$,'negative no-prepare witness is retired through authenticated device boundary');
select ok((select aborted from public.payment_history_local_intents where operation_id=(pg_temp.case_input('a-duplicate')->>'operation_id')::uuid),'original negative intent cannot later resurrect');

insert into public.payment_history_role_permissions(shop_id,role_key,capability,enabled) values('10000000-0000-4000-8000-000000403019','pos_admin','migrate',false);
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload())$$,'42501','payment_history_device_denied','response recovery rechecks current migration permission');
delete from public.payment_history_role_permissions where shop_id='10000000-0000-4000-8000-000000403019' and role_key='pos_admin' and capability='migrate';
update public.pos_sessions set status='revoked',revoked_at=clock_timestamp() where pos_session_id='60000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.baseline_request(1,'upload_create',pg_temp.upload_payload())$$,'42501','payment_history_device_denied','revoked lease cannot recover a signed object target');
select ok((select count(*)=0 from public.payment_history_movement_versions) and (select count(*)=0 from public.pos_sales),'source admission creates no bank or native sale');
select is((select value->>'object_key' from state where key='first'),'history/10000000-0000-4000-8000-000000403019/'||(select value->>'upload_id' from state where key='first'),'object key is derived only from authenticated shop and owned upload');
select * from finish();
rollback;
